#!/usr/bin/env python3
# Builds batch 3's MANIFEST block for climb-batch-workflow.js from CLIMB-BATCH-3.md
# and splices it in place of the block between the two marker lines.
import re, sys

REPO = '/home/user/fortress'
MD = REPO + '/explorations/coordinator/CLIMB-BATCH-3.md'
JS = REPO + '/explorations/coordinator/climb-batch-workflow.js'

md = open(MD, encoding='utf-8').read().split('\n')

# The rung sections: every "### X. title" under "## The six rungs", up to "## How it is run".
start = md.index('## The six rungs')
end = md.index('## How it is run')
sections = {}
order = []
cur = None
for line in md[start + 1:end]:
    m = re.match(r'^### ([A-Z])\. (.*)$', line)
    if m:
        cur = m.group(1)
        order.append(cur)
        sections[cur] = {'title': m.group(2), 'body': []}
        continue
    if cur:
        sections[cur]['body'].append(line)
for k in sections:
    b = sections[k]['body']
    while b and b[0] == '':
        b.pop(0)
    while b and b[-1] == '':
        b.pop()
assert order == ['P', 'L', 'C', 'R', 'S', 'M'], order


def js(s):
    """A JS double-quoted string literal: backticks dropped (the file carries none,
    as batch 1's and batch 2's tails carry none), backslashes and double quotes
    escaped, and every non-ASCII character as a \\u escape so the file stays ASCII
    while the string's value is the record's text."""
    s = s.replace('`', '')
    out = []
    for ch in s:
        if ch == '\\':
            out.append('\\\\')
        elif ch == '"':
            out.append('\\"')
        elif ord(ch) > 127:
            assert ord(ch) <= 0xFFFF
            out.append('\\u%04x' % ord(ch))
        else:
            out.append(ch)
    return '"' + ''.join(out) + '"'


RUNGS = [
    # id, slug, path, branch, expectedMinutes, writesState, testIsStage, expectedCheckerCount, blurb
    ('P', 'rung-exclusion-relax', '/home/user/fortress-exclusion', 'wip/rung-exclusion-relax', 60, False, False, 33,
     "the checker's fourth exclusion clause, checkP (TypeAnalyzer.scala), which makes two instantiations of one generic exclude each other against Specification/basic/trait-parameters.tex:339-345, stops contributing from the two type-hierarchy checks and from the overloading checker's exclusion test; checkP stays and notExcludes is unchanged. Scala; the checker count goes 93 -> 33 on its own branch, and to 23 with L."),
    ('L', 'rung-library-defects', '/home/user/fortress-defects', 'wip/rung-library-defects', 60, False, True, 102,
     "the five plain defects in the interpreter library's apis: fifteen RangeInternals.fsi bounds, String's duplicated split and splitWithOffsets, List.fsi's zip, Condition.map, and the free comprises at FortressLibrary.fsi:373. Library/ only; its test is the checker-count stage (testIsStage), 93 -> 102 on its own branch."),
    ('C', 'rung-library-comments', '/home/user/fortress-comments', 'wip/rung-library-comments', 20, False, False, None,
     "four comments and no code in Library/FortressLibrary.fss and .fsi: the closure's NOT YET note, why Array3 excludes AnyAdditiveGroup, what the reversed - means, and the scalar block's unsized return. No test; both suites byte-identical before and after."),
    ('R', 'rung-round-half-even', '/home/user/fortress-round', 'wip/rung-round-half-even', 30, False, False, None,
     "round on a float sends an exact half to the even integer: Math.round becomes (long) Math.rint in the interpreter glue's Float.java and RR32.java (ledger row 329). Java; one new interpreter test in ProjectFortress/tests/, so testSystem goes 384 -> 385."),
    ('S', 'rung-default-rendering', '/home/user/fortress-rendering', 'wip/rung-default-rendering', 60, False, False, None,
     "a compiled object with no asString of its own prints its bare Fortress type name with its static arguments (Box, Box[\\ZZ32\\], Pt), through one new native in nativeHelpers/stringOps.java behind the compiled Object.asString default (ledger row 321). Java plus a body and an import in CompilerBuiltin.fss; today such an object overflows the stack."),
    ('M', 'rung-analyzer-memo', '/home/user/fortress-memo', 'wip/rung-analyzer-memo', 45, True, True, None,
     "a memo for TypeAnalyzer.parents and excludesClause, held on TraitTable behind a ProjectProperties switch: the whole-library check 21 s -> 13 s with no answer changed. Scala; its test is the checker-count stage unchanged line for line (testIsStage); separable, the rung to drop for one fewer .scala rung."),
]
bymeta = {r[0]: r for r in RUNGS}


def title_for(k):
    t = sections[k]['title'].replace('`', '')
    if t.startswith('The '):
        t = 't' + t[1:]
    return t


def tail(k):
    _, slug, path, branch = bymeta[k][:4]
    lines = ['',
             '## Your rung: %s - %s' % (k, title_for(k)),
